CREATE TABLE calendar(d DATE,t TIME(3),ts TIMESTAMP(3),v VARCHAR);
INSERT INTO calendar VALUES(DATE '2000-01-31',TIME '23:59:59.123',TIMESTAMP '2000-01-31 23:59:59.123','2000-01-31 23:59:59.123456789');
SELECT DATEADD(month,1,d),DATEADD(second,1,t),DATEADD(ns,1,ts),DATEADD(day,1,v) FROM calendar;
SELECT DATEADD(day,1,DATEADD(month,1,d)),TIMESTAMPDIFF(day,d,DATEADD(month,1,d)) FROM calendar;
SELECT 1+d+1,d-1,2+ts+2,ts-2 FROM calendar;
CREATE TABLE shifted AS SELECT DATEADD(month,1,d) AS d,DATEADD(second,1,ts) AS ts,DATEDIFF(day,d,DATEADD(month,1,d)) AS n FROM calendar;
TABLE shifted;
SELECT d FROM calendar WHERE DATEDIFF(day,d,DATE '2000-02-01')=1;
SELECT DATEADD(month,1,d) AS d FROM calendar UNION SELECT DATE '2000-02-29';
WITH RECURSIVE months(d) AS (VALUES DATE '2000-01-31' UNION ALL SELECT DATEADD(month,1,d) FROM months WHERE d<DATE '2000-04-01') TABLE months;
SELECT DATEDIFF(month,d,DATE '2000-03-01') AS n,COUNT(*) AS c FROM calendar GROUP BY d;
SELECT DATEADD(day,1,TIME '12:00:00') AS bad FROM calendar WHERE FALSE;
CREATE TABLE saved(d DATE DEFAULT DATEADD(month,1,(SELECT MAX(d) FROM calendar)),n BIGINT DEFAULT DATEDIFF(day,DATE '2000-01-01',(SELECT MAX(d) FROM calendar)));
INSERT INTO saved DEFAULT VALUES;
UPDATE calendar SET d=DATEADD(month,1,d);
INSERT INTO saved DEFAULT VALUES;
TABLE saved ORDER BY d;
DROP TABLE saved,shifted,calendar;
